function dump(n, depth) {
  let s = "  ".repeat(depth) + n.name + " [" + n.type + "] " + Math.round(n.width) + "x" + Math.round(n.height);
  if (n.fills && n.fills !== figma.mixed && n.fills.length) {
    s += " fills=" + JSON.stringify(n.fills.map(f => f.type === "IMAGE" ? {type:"IMAGE", hash: f.imageHash, scaleMode: f.scaleMode} : {type:f.type, color:f.color, opacity:f.opacity})).slice(0,300);
  }
  if (n.type === "TEXT") {
    s += " chars=" + JSON.stringify(n.characters) + " font=" + JSON.stringify(n.fontName) + " size=" + n.fontSize + " color=" + JSON.stringify(n.fills[0] && n.fills[0].color);
  }
  if (n.cornerRadius !== undefined && n.cornerRadius !== 0) s += " r=" + n.cornerRadius;
  if (n.rectangleCornerRadii) s += " radii=" + JSON.stringify(n.rectangleCornerRadii);
  if (n.strokes && n.strokes.length) s += " strokes=" + JSON.stringify(n.strokes.map(st=>st.color)) + " sw=" + n.strokeWeight;
  if (n.effects && n.effects.length) s += " effects=" + JSON.stringify(n.effects).slice(0,200);
  if (n.clipsContent !== undefined) s += " clip=" + n.clipsContent;
  let out = [s];
  if (n.children && depth < 4) for (const c of n.children) out = out.concat(dump(c, depth+1));
  return out;
}
