const ids = ["1:163","1:164","1:165","1:166","1:167","1:168","1:169","1:141","1:143","1:144","1:145","1:146","1:147","1:148","1:149","1:150","1:151","1:152","1:153","1:154","1:157"];
const out = [];
for (const id of ids) {
  const n = await figma.getNodeByIdAsync(id);
  let s = id + " " + n.name;
  if (n.fills && n.fills !== figma.mixed && n.fills.length && n.fills[0].type === "IMAGE") s += " hash=" + n.fills[0].imageHash;
  // find vector colors
  const vecs = n.findAll ? n.findAll(x => x.type === "VECTOR") : [];
  const cols = vecs.map(v => {
    const f = v.fills && v.fills !== figma.mixed && v.fills[0] && v.fills[0].type === "SOLID" ? "f:" + JSON.stringify(v.fills[0].color) : "";
    const st = v.strokes && v.strokes.length ? "s:" + JSON.stringify(v.strokes[0].color) : "";
    return f + st;
  });
  s += " vecs=[" + [...new Set(cols)].join(" | ") + "]";
  out.push(s);
}
return out.join("\n");

