function T(chars,size,style,color){
  const t=figma.createText(); t.fontName={family:"DM Sans",style}; t.fontSize=size; t.characters=chars;
  t.fills=[{type:"SOLID",color}]; t.name="T·"+chars.slice(0,24); return t;
}
function R(w,h,color,r){const n=figma.createRectangle();n.resize(w,h);n.fills=[{type:"SOLID",color}];if(r!==undefined)n.cornerRadius=r;return n;}
function AL(dir,gap,pad){const f=figma.createFrame();f.layoutMode=dir;f.itemSpacing=gap;
  if(pad){f.paddingLeft=pad[0];f.paddingTop=pad[1];f.paddingRight=pad[2];f.paddingBottom=pad[3];}
  f.primaryAxisSizingMode="AUTO";f.counterAxisSizingMode="AUTO";f.fills=[];return f;}
