async function rating(n){
  const r=await inst("9:14");
  const stars=r.children.filter(c=>c.type==="INSTANCE");
  for(let i=0;i<5;i++){
    const want = i<n ? FILLED : OUTLINE;
    if(stars[i].mainComponent!==want) stars[i].swapComponent(want);
    // recolor
    const vecs=stars[i].findAll(x=>x.type==="VECTOR");
    for(const v of vecs){
      if(i<n){ v.fills=solid({r:1,g:0.77,b:0.15}); v.strokes=[]; }
      else { v.fills=[]; v.strokes=solid({r:0.80,g:0.80,b:0.82}); v.strokeWeight=1.2; }
    }
  }
  return r;
}
