function section(title,rows){
  const wrap=figma.createFrame();
  wrap.name="Section_"+title.replace(/\s/g,"");
  wrap.layoutMode="VERTICAL";
  wrap.itemSpacing=8;
  wrap.paddingLeft=20;wrap.paddingRight=20;wrap.paddingTop=20;wrap.paddingBottom=0;
  wrap.fills=[];
  f.appendChild(wrap);wrap.layoutSizingHorizontal="FILL";
  const lbl=figma.createText();
  lbl.fontName={family:"DM Sans",style:"Medium"};
  lbl.characters=title;lbl.fontSize=12;
  lbl.fills=[{type:"SOLID",color:GRAY}];
  wrap.appendChild(lbl);
  const card=figma.createFrame();
  card.name="Card";
  card.layoutMode="VERTICAL";
  card.itemSpacing=0;
  card.cornerRadius=16;
  card.clipsContent=true;
  card.fills=[{type:"SOLID",color:{r:1,g:1,b:1}}];
  wrap.appendChild(card);card.layoutSizingHorizontal="FILL";
  rows.forEach((r,i)=>{
    const inst=PR.createInstance();
    card.appendChild(inst);
    inst.layoutSizingHorizontal="FILL";
    const t=inst.findOne(x=>x.name==="Label");
    t.characters=r[0];
    t.fills=[{type:"SOLID",color:r[1]||DARK}];
    if(i>0){
      const div=figma.createRectangle();
      div.name="Divider";
      div.resize(10,1);
      div.fills=[{type:"SOLID",color:{r:0.93,g:0.94,b:0.95}}];
      card.insertChild(card.children.length-1,div);
      div.layoutSizingHorizontal="FILL";
    }
  });
  return wrap;
}

