async function hotspot(frameId,targetId,dest,label){
  const f=await figma.getNodeByIdAsync(frameId);
  const t=await figma.getNodeByIdAsync(targetId);
  if(!t){out.push("MISS target "+label);return;}
  const bb=t.absoluteBoundingBox;
  const fbb=f.absoluteBoundingBox;
  const r=figma.createRectangle();
  r.name="Hotspot · "+label;
  r.fills=[];
  r.resize(Math.max(bb.width,24),Math.max(bb.height,24));
  f.appendChild(r);
  r.layoutPositioning="ABSOLUTE";
  r.x=bb.x-fbb.x-(r.width-bb.width)/2;
  r.y=bb.y-fbb.y-(r.height-bb.height)/2;
  r.reactions=nav(dest);
  out.push("OK "+label+" @"+Math.round(r.x)+","+Math.round(r.y));
}
